WITH grouped_data AS ( SELECT MSEQ, MSG_TYPE, DSTADDR, CALLBACK, STAT, SUBJECT, TEXT, INSERT_TIME, REQUEST_TIME, SENDER_CODE, EXT_COL0, EXT_COL1, EXT_COL2, EXT_COL3, FILECNT, FILELOC1, FILELOC2, FILELOC3, ROW_NUMBER() OVER (PARTITION BY CASE WHEN EXT_COL0 IS NULL THEN EXT_COL1 ELSE CONCAT(EXT_COL0, '_', DATE_FORMAT(INSERT_TIME, '%Y%m%d%H'), LPAD(FLOOR(MINUTE(INSERT_TIME)/2)*2, 2, '0'), '_', REQUEST_TIME) END, MSG_TYPE ORDER BY MSEQ) as rn, COUNT(*) OVER (PARTITION BY CASE WHEN EXT_COL0 IS NULL THEN EXT_COL1 ELSE CONCAT(EXT_COL0, '_', DATE_FORMAT(INSERT_TIME, '%Y%m%d%H'), LPAD(FLOOR(MINUTE(INSERT_TIME)/2)*2, 2, '0'), '_', REQUEST_TIME) END, MSG_TYPE) as message_count FROM msg_queue
1=1
EXT_COL3 IN
#{accountId}
EXT_COL3 = #{userId}
1=0
AND REQUEST_TIME > current_timestamp
AND MSG_TYPE = #{msgType}
AND TEXT LIKE CONCAT('%', #{searchText}, '%')
) SELECT MSEQ as mSeq, MSG_TYPE as msgType, DSTADDR as dstAddr, CALLBACK as callBack, STAT as stat, SUBJECT as subject, TEXT as text, INSERT_TIME as insertTime, REQUEST_TIME as requestTime, SENDER_CODE as senderCode, EXT_COL0 as extCol0, EXT_COL1 as extCol1, EXT_COL2 as extCol2, EXT_COL3 as extCol3, message_count as messageCount, FILECNT as fileCnt, FILELOC1 as fileLoc1, FILELOC2 as fileLoc2, FILELOC3 as fileLoc3 FROM grouped_data WHERE rn = 1 ORDER BY INSERT_TIME DESC, EXT_COL1 DESC
LIMIT #{offset}, #{limit}

WITH grouped_data AS ( SELECT MSEQ, MSG_TYPE, EXT_COL0, EXT_COL1, INSERT_TIME, REQUEST_TIME, ROW_NUMBER() OVER (PARTITION BY CASE WHEN EXT_COL0 IS NULL THEN EXT_COL1 ELSE CONCAT(EXT_COL0, '_', DATE_FORMAT(INSERT_TIME, '%Y%m%d%H'), LPAD(FLOOR(MINUTE(INSERT_TIME)/2)*2, 2, '0'), '_', REQUEST_TIME) END, MSG_TYPE ORDER BY MSEQ) as rn FROM msg_queue
1=1
EXT_COL3 IN
#{accountId}
EXT_COL3 = #{userId}
1=0
AND REQUEST_TIME > current_timestamp
AND MSG_TYPE = #{msgType}
AND TEXT LIKE CONCAT('%', #{searchText}, '%')
) SELECT COUNT(*) FROM grouped_data WHERE rn = 1

SELECT MSEQ as mSeq, MSG_TYPE as msgType, DSTADDR as dstAddr, CALLBACK as callBack, STAT as stat, SUBJECT as subject, TEXT as text, FILECNT as fileCnt, FILELOC1 as fileLoc1, FILELOC2 as fileLoc2, FILELOC3 as fileLoc3, FILELOC4 as fileLoc4, FILELOC5 as fileLoc5, INSERT_TIME as insertTime, REQUEST_TIME as requestTime, SENDER_CODE as senderCode, EXT_COL0 as extCol0, EXT_COL1 as extCol1, EXT_COL2 as extCol2, EXT_COL3 as extCol3 FROM msg_queue
MSEQ = #{mSeq}
AND EXT_COL3 IN
#{accountId}
AND EXT_COL3 = #{userId}
AND 1=0

mapper.update:
UPDATE msg_queue
SET REQUEST_TIME = #{newRequestTime}
WHERE
    EXT_COL3 = #{userId}
    AND MSG_TYPE = #{msgType}
    AND (
        (EXT_COL0 IS NULL AND EXT_COL1 = (
            SELECT EXT_COL1 FROM msg_queue m2
            WHERE m2.EXT_COL3 = #{userId}
            AND m2.MSG_TYPE = #{msgType}
            AND m2.INSERT_TIME = #{insertTime}
            AND m2.EXT_COL0 IS NULL
            LIMIT 1
        ))
        OR
        (EXT_COL0 IS NOT NULL AND EXT_COL0 = (
            SELECT EXT_COL0 FROM msg_queue m2
            WHERE m2.EXT_COL3 = #{userId}
            AND m2.MSG_TYPE = #{msgType}
            AND m2.INSERT_TIME = #{insertTime}
            AND m2.EXT_COL0 IS NOT NULL
            LIMIT 1
        ) AND CONCAT(DATE_FORMAT(INSERT_TIME, '%Y%m%d%H'),
            LPAD(FLOOR(MINUTE(INSERT_TIME)/2)*2, 2, '0')) =
            CONCAT(DATE_FORMAT(#{insertTime}, '%Y%m%d%H'),
            LPAD(FLOOR(MINUTE(#{insertTime})/2)*2, 2, '0'))
            AND REQUEST_TIME = (
            SELECT REQUEST_TIME FROM msg_queue m3
            WHERE m3.EXT_COL3 = #{userId}
            AND m3.MSG_TYPE = #{msgType}
            AND m3.INSERT_TIME = #{insertTime}
            AND m3.EXT_COL0 IS NOT NULL
            LIMIT 1
        ))
    )

